## Code Example
```javascript
// Fetch wrapper
async function fetchFeed(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error('Network error');
  return res.json();
}

// WebSocket manager with backoff
function createFeedWS(url, onUpdate) {
  let ws = new WebSocket(url);
  let retry = 0;
  ws.onmessage = (ev) => {
    const item = JSON.parse(ev.data);
    onUpdate(item);
  };
  ws.onclose = () => {
    const delay = Math.min(30000, 1000 * Math.pow(2, retry++));
    setTimeout(() => {
      ws = createFeedWS(url, onUpdate);
    }, delay);
  };
  return ws;
}

// Simple feed renderer with dedupe
const seen = new Set();
function handleUpdate(item) {
  if (seen.has(item.id)) return;
  seen.add(item.id);
  const li = document.createElement('li');
  li.textContent = item.text;
  feedList.prepend(li); // minimal DOM update
}

